package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"unsafe"
)

// #include <stdlib.h>
// #include <string.h>
import "C"

const MAX_PIPELINE_NAME_LEN = 64

// PipelineConfig holds the native buffer for pipeline name processing
type PipelineConfig struct {
	nameBuffer [64]byte
	priority   int32
	enabled    bool
}

// ProcessPipelineName copies the pipeline name into a fixed-size native buffer
// for compatibility with the legacy C plugin interface
func ProcessPipelineName(name string) (*PipelineConfig, error) {
	config := &PipelineConfig{}

	// Legacy C interop: copy name into fixed buffer using memcpy
	// This maintains compatibility with the native plugin ABI
	nameBytes := []byte(name)

	// BUG: No length check before memcpy into fixed 64-byte buffer
	dstPtr := unsafe.Pointer(&config.nameBuffer[0])
	srcPtr := unsafe.Pointer(&nameBytes[0])
	C.memcpy(dstPtr, srcPtr, C.size_t(len(nameBytes)))

	config.priority = 1
	config.enabled = true

	return config, nil
}

// handleTrigger processes incoming CI/CD pipeline trigger requests
func handleTrigger(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Failed to read body", http.StatusBadRequest)
		return
	}
	defer r.Body.Close()

	pipelineName := string(body)

	// Process the pipeline name through legacy native interface
	config, err := ProcessPipelineName(pipelineName)
	if err != nil {
		http.Error(w, fmt.Sprintf("Processing error: %v", err), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Pipeline '%s' triggered (priority=%d)\n", 
		string(config.nameBuffer[:]), config.priority)
}

// handleHealth provides basic health check endpoint
func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("OK"))
}

func main() {
	listenAddr := os.Getenv("LISTEN_ADDR")
	if listenAddr == "" {
		listenAddr = ":8080"
	}

	http.HandleFunc("/api/v1/trigger", handleTrigger)
	http.HandleFunc("/healthz", handleHealth)

	fmt.Printf("CI/CD Pipeline Plugin v2.3.1 listening on %s\n", listenAddr)
	if err := http.ListenAndServe(listenAddr, nil); err != nil {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
